use super::*;
use crate::cn::wps::moss::app::{KmoBookApi::KmoBookApi,event::{KmoBookOpenEventListener::KmoBookOpenEventListener,KmoBookChangeEventsListener::KmoBookChangeEventsListener}};
use crate::cn::wps::moss::xlsxr::util::UnifiedXmlReader::UnifiedXmlReader;
use serde_json::{Value,json};
struct Open{book:Rc<KmoBook>,trace:Rc<RefCell<Vec<Value>>>,mode:i32}
impl KmoBookOpenEventListener for Open{fn bookDidFinishInitializing(&self,b:&KmoBook){self.trace.borrow_mut().push(json!({"call":"open","sameBook":std::ptr::eq(self.book.as_ref(),b),"sheets":b.sheetCount()}));if self.mode==1{panic!("IllegalStateException: open listener");}}}
struct Change{book:Rc<KmoBook>,trace:Rc<RefCell<Vec<Value>>>,mode:i32}
impl KmoBookChangeEventsListener for Change{fn bookDidFinishInitializing(&self){self.trace.borrow_mut().push(json!({"call":"change","sheets":self.book.sheetCount()}));if self.mode==2{panic!("IllegalStateException: change listener");}}fn bookSettingsDidFinishChanging(&self){}fn bookContentsDidFinishChanging(&self){}fn sheetDidFinishActivating(&self){}}
fn call(f:impl FnOnce())->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(_)=>json!({"result":"ok","value":null}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let name=["NullPointerException","IllegalStateException","RuntimeException"].into_iter().find(|n|s.starts_with(n)).unwrap_or(s);json!({"result":name})}}}
#[test]fn original_android_declared_sheets_finish_listener_order(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/sheets-finish-r0b64");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();let mut rows=vec![];for p in input["cases"].as_array().unwrap(){let mode=p["mode"].as_i64().unwrap()as i32;let trace=Rc::new(RefCell::new(vec![]));let open=Rc::new(Open{book:book.clone(),trace:trace.clone(),mode});let change:Rc<dyn KmoBookChangeEventsListener>=Rc::new(Change{book:book.clone(),trace:trace.clone(),mode});book.subscribeChangeEvents(Some(change.clone()));let reader=XlsxrWorkbook::XlsxrWorkbook(book.clone(),None,if mode==3{None}else{Some(open)},None);let mut row=call(||UnifiedXmlReader::read(&mut std::io::Cursor::new(p["xml"].as_str().unwrap().as_bytes()),Box::new(WorkbookHandler::WorkbookHandler(book.clone(),reader))).unwrap());row["trace"]=json!(trace.borrow().clone());book.unsubscribeChangeEvents(Some(&change));rows.push(row);}let actual=json!({"cases":rows});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();assert_eq!(actual,java);}
